import React from "react";
import { Outlet, Route, Routes } from "react-router-dom";

import { AppHeader, AppNavigator, RenderAvailableConfig } from "./components";
import { DashboardLinks } from "./components/DashboardLinks";
import { NoMatch } from "./components/NoMatch";
import {
    AppContext,
    setActivePage,
    setDashboardLinks,
    setDashboardProps,
    setFormLinks,
    setShowFullMenu,
    setUserNavLinks,
} from "./context";
import { fetchInitialData } from "./remote";

import "./App.less";
import "./remote";
import { Helmet } from "react-helmet";

const resource = fetchInitialData();

function App() {
    const { state, dispatch } = React.useContext(AppContext);
    const dataProps = resource.payslip.read();

    React.useEffect(() => {
        if (dataProps.navLinks.length) {
            dispatch(setDashboardLinks(dataProps.appLinks));
            dispatch(setUserNavLinks(dataProps.navLinks));
            dispatch(setFormLinks(dataProps.formLinks));
            dispatch(setActivePage(dataProps.activePage));
            dispatch(setDashboardProps(dataProps.dashboadProps));
        }

        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
        <Routes>
            <Route path="/" element={<Layout />}>
                <Route
                    index
                    element={
                        <>
                            <Helmet>
                                <title>App Configuration</title>
                            </Helmet>
                            <div className="ss-app-config-wrap">
                                <DashboardLinks />
                            </div>
                        </>
                    }
                />
                <Route path="Dashboard" element={<RenderAvailableConfig name="Dashboard" label="Dashboard" />} />
                {(state.dashboardLinks || []).map((link) => (
                    <Route
                        path={link.Name}
                        element={<RenderAvailableConfig name={link.Name} label={link.Link.Text} />}
                    />
                ))}
                <Route
                    path="DocumentSignatures"
                    element={<RenderAvailableConfig name="DocumentSignatures" label="Document Signatures" />}
                />
                <Route
                    path="Announcements"
                    element={<RenderAvailableConfig name="Announcements" label="Announcements" />}
                />
                <Route
                    path="*"
                    element={
                        <div className="ss-app-config-wrap">
                            <NoMatch />
                        </div>
                    }
                />
            </Route>
        </Routes>
    );
}

const Layout = () => {
    const { state, dispatch } = React.useContext(AppContext);

    return (
        <>
            <AppHeader title="" onMenuClick={() => dispatch(setShowFullMenu(!state.showFullMenu))} />
            {state.navLinks.length && (
                <AppNavigator
                    showFullMenu={state.showFullMenu}
                    onCollapseBtnClick={() => dispatch(setShowFullMenu(!state.showFullMenu))}
                />
            )}

            <div className="ss-app-config-body">
                <Outlet />
            </div>
        </>
    );
};

export default App;
