import React, { createContext, useReducer } from "react";
import { getInitialData, saveConfig } from "../remote";
import {
    DashboardLink,
    FormLink,
    SSLinkProp,
    NavigationRoute,
    DBForm,
} from "../types";
import {
    Actions,
    ActionType,
    setDashboardLinks,
    setDashboardProps,
    setFormLinks,
    setUserNavLinks,
} from "./actions";

export const ReservedLinks = [
    "/Profile/Security",
    "/Profile/Approvals",
    "/Profile/PeopleStreme",
    "/CleverForms/Inbox",
    "/CleverForms/Template",
    "/CleverForms/Admin",
];

export const ReservedNames = [
    "MyDocuments",
    "BankAccounts",
    "StaffSearch",
    "Leave",
    "MyPay",
    "MyAccount",
    "WorkSchedules",
    "CleverForms",
    "Timesheets",
];

interface IState {
    isAuth: boolean;
    fetchingData: boolean;
    showFullMenu: boolean;
    currentPage: any;
    showAllPayslip: boolean;
    latestYear: number;
    navLinks: NavigationRoute[];
    formLinks?: FormLink[];
    dashboardLinks: DashboardLink[];
    activePage: string;
    dashboardProps: SSLinkProp;
}

const initialState: IState = {
    isAuth: false,
    fetchingData: false,
    showFullMenu: window.innerWidth > 1200, // MENU open in larger screen
    currentPage: "",
    showAllPayslip: false,
    latestYear: 0,
    navLinks: [],
    activePage: "dashboard",
    dashboardLinks: [],
    dashboardProps: {
        Id: "",
        Url: "",
    },
};

interface IAppContext {
    state: IState;
    dispatch: React.Dispatch<Actions>;
    saveDashboardConfig: (values: DBForm) => Promise<void>;
}

const AppContext = createContext<IAppContext>({
    state: initialState,
    dispatch: () => null,
    saveDashboardConfig: async () => Promise.resolve(),
});

const { Provider } = AppContext;

const reducer = (state: IState, action: Actions) => {
    switch (action.type) {
        case ActionType.SetFetchingData:
            return {
                ...state,
                fetchingData: action.payload,
            };

        case ActionType.SetShowFullMenu:
            return {
                ...state,
                showFullMenu: action.payload,
            };

        case ActionType.SetCurrentPage:
            return {
                ...state,
                currentPage: action.payload,
            };

        case ActionType.SetUserNavLinks:
            return {
                ...state,
                navLinks: action.payload,
            };

        case ActionType.SetUserLinks:
            return {
                ...state,
                formLinks: action.payload,
            };

        case ActionType.SetActivePage:
            return {
                ...state,
                activePage: action.payload,
            };

        case ActionType.SetDashboardLinks:
            return {
                ...state,
                dashboardLinks: action.payload,
            };

        case ActionType.SetDashboardProps:
            return {
                ...state,
                dashboardProps: action.payload,
            };

        default:
            return state;
    }
};

const AppProvider = ({ children }: { children: JSX.Element }) => {
    const [state, dispatch] = useReducer(reducer, initialState);

    const saveDashboardConfig = async (values: DBForm) => {
        return await saveConfig(values)
            .then(async (res) => {
                const { appLinks, navLinks, formLinks, dashboadProps } =
                    await getInitialData();
                dispatch(setDashboardLinks(appLinks));
                dispatch(setUserNavLinks(navLinks));
                dispatch(setFormLinks(formLinks));
                dispatch(setDashboardProps(dashboadProps));
            })
            .catch(() => {});
    };

    return (
        <Provider
            value={{
                state,
                dispatch,
                saveDashboardConfig,
            }}
        >
            {children}
        </Provider>
    );
};

export { AppContext, AppProvider };
