import React from "react";
import { Button, Checkbox, Form, Input, Modal, Spin } from "antd";
import Table, { ColumnsType } from "antd/lib/table";

import { deleteDocSignaturesConfig, getDocSignaturesConfig, saveDocSignaturesConfig } from "../../remote";
import { DocumentSignature, DSRoles } from "../../types";
import { ConfigHeading } from "../ConfigHeading";
import { AppIcon } from "../SVGFiles";

export const AppDocumentSignatures = () => {
    const [docSignatures, setDocSignatures] = React.useState<DocumentSignature[]>();
    const [isModalOpen, setIsModalOpen] = React.useState(false);
    const [showDelDocSig, setShowDelDocSig] = React.useState(false);
    const [selectedDocSig, setSelectedDocSig] = React.useState<DocumentSignature>();

    React.useEffect(() => {
        fetchDocSignatures();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const fetchDocSignatures = async () => {
        const { status, data } = await getDocSignaturesConfig();
        if (status === 200) {
            setDocSignatures(data);
        }
    };

    const createDocSignature = () => {
        setIsModalOpen(true);
        setSelectedDocSig(undefined);
    };

    const updateDocSignature = (doc: DocumentSignature) => {
        setIsModalOpen(true);
        for (let N = 0; N < 4; N++) {
            if (!doc.Roles[N]) {
                doc.Roles.push({
                    Name: "",
                    Order: N + 1,
                });
            }
        }
        setSelectedDocSig(doc);
    };

    const deleteModal = () => (
        <Modal
            centered
            open={showDelDocSig}
            footer={[
                <Button
                    type="primary"
                    size="small"
                    onClick={async () => {
                        setShowDelDocSig(false);
                        await deleteDocSignaturesConfig(selectedDocSig?.Id || "");
                        await fetchDocSignatures();
                        setSelectedDocSig(undefined);
                    }}>
                    Yes
                </Button>,
                <Button
                    danger
                    type="primary"
                    size="small"
                    onClick={() => {
                        setSelectedDocSig(undefined);
                        setShowDelDocSig(false);
                    }}>
                    No
                </Button>,
            ]}>
            <span className="f-16">
                Are you sure you want to delete template <strong>{selectedDocSig?.Title}</strong>?
            </span>
        </Modal>
    );

    const COLS: ColumnsType<DocumentSignature> = [
        {
            title: "Template ID",
            dataIndex: "ExternalTemplateId",
            key: "ExternalTemplateId",
        },
        {
            title: "Description",
            dataIndex: "Description",
            key: "Description",
        },
        {
            title: "Title",
            dataIndex: "Title",
            key: "Title",
        },
        {
            title: "Enabled",
            dataIndex: "Enabled",
            key: "Enabled",
            render: (_, { Enabled }) => <Checkbox value={Enabled} disabled />,
        },
        {
            title: "",
            width: 90,
            className: "text-right",
            render: (_, doc) => (
                <span>
                    <Button
                        size="small"
                        icon={<AppIcon asset="edit" width="16" height="16" stroke="#ffffff" />}
                        type="primary"
                        shape="circle"
                        onClick={() => {
                            updateDocSignature(doc);
                        }}
                    />
                    <Button
                        danger
                        size="small"
                        icon={<AppIcon asset="delete" width="16" height="16" stroke="#ffffff" />}
                        type="primary"
                        shape="circle"
                        className="m-l-8"
                        onClick={() => {
                            setSelectedDocSig(doc);
                            setShowDelDocSig(true);
                        }}
                    />
                </span>
            ),
        },
    ];

    return (
        <Spin spinning={docSignatures === undefined} tip="Loading data...">
            <ConfigHeading
                title="Document Signatures"
                noSaveBtn={true}
                buttons={
                    <Button
                        icon={<AppIcon asset="paper-plus" width="20" height="20" stroke="#1268b3" />}
                        type="link"
                        onClick={() => {
                            createDocSignature();
                        }}>
                        <span className="m-l-4">Create</span>
                    </Button>
                }
            />
            <div className="ss-app-config-box shadow">
                <Table columns={COLS} dataSource={docSignatures} pagination={false} prefixCls="ss-app-config-table" />
            </div>
            <DocSignatureForm
                open={isModalOpen}
                onCancel={() => setIsModalOpen(false)}
                onSaved={async (values) => {
                    await saveDocSignaturesConfig({
                        ...values,
                    });

                    await fetchDocSignatures();
                    setIsModalOpen(false);
                }}
                docSignature={selectedDocSig}
            />
            {deleteModal()}
        </Spin>
    );
};

const DocSignatureForm: React.FC<{
    open: boolean;
    onSaved: (doc: DocumentSignature) => void;
    onCancel: () => void;
    docSignature?: DocumentSignature;
}> = ({ open, onSaved, onCancel, docSignature }) => {
    const [formDisabled, setFormDisabled] = React.useState(false);
    const [form] = Form.useForm<DocumentSignature>();

    React.useEffect(() => {
        if (docSignature) {
            form.setFieldsValue(docSignature);
        } else {
            let Roles: DSRoles[] = [];
            for (let indx = 0; indx < 4; indx++) {
                Roles.push({
                    Name: "",
                    Order: indx + 1,
                });
            }
            form.setFieldsValue({
                Title: "",
                Description: "",
                EmailSubject: "",
                EmailBody: "",
                Enabled: false,
                ExternalTemplateId: "",
                Id: "",
                Roles,
            });
        }
        setFormDisabled(false);
    }, [docSignature, form]);

    const onFinish = async (values: DocumentSignature) => {
        setFormDisabled(true);
        onSaved(values);
    };

    return (
        <Modal
            title={docSignature ? `Update: ${docSignature.Title}` : "New Document Signature"}
            open={open}
            onOk={() => {
                form.submit();
            }}
            onCancel={onCancel}
            okType="primary"
            okText="Save"
            okButtonProps={{
                disabled: formDisabled,
            }}
            cancelButtonProps={{
                danger: true,
                disabled: formDisabled,
            }}
            centered={true}>
            <Form
                name="ss-links"
                onFinish={onFinish}
                autoComplete={"off"}
                layout="horizontal"
                form={form}
                disabled={formDisabled}>
                {docSignature && (
                    <Form.Item name={["Id"]} noStyle>
                        <Input type="hidden" />
                    </Form.Item>
                )}
                <Form.Item name={["ExternalTemplateId"]} label="Document Id">
                    <Input disabled={docSignature !== undefined} />
                </Form.Item>
                <Form.Item
                    name={["Description"]}
                    label="Description"
                    rules={[
                        {
                            required: true,
                            message: "Description field is required.",
                        },
                    ]}>
                    <Input />
                </Form.Item>
                <RolesFormList />
                <Form.Item
                    name={["Title"]}
                    label="Title"
                    rules={[
                        {
                            required: true,
                            message: "Title field is required",
                        },
                    ]}>
                    <Input />
                </Form.Item>
                <Form.Item name={["EmailSubject"]} label="Email Subject">
                    <Input />
                </Form.Item>
                <Form.Item name={["EmailBody"]} label="Email Body">
                    <Input />
                </Form.Item>
                <Form.Item name={["Enabled"]} label="Enabled" valuePropName="checked">
                    <Checkbox />
                </Form.Item>
            </Form>
        </Modal>
    );
};

const RolesFormList = () => (
    <Form.List name={["Roles"]}>
        {(fields) => (
            <>
                {fields.map(({ key, name }) => (
                    <Form.Item
                        key={key}
                        name={[name, "Name"]}
                        label={`Role Title ${key + 1}`}
                        rules={[
                            {
                                required: key === 0,
                                message: "Role title is required.",
                            },
                        ]}>
                        <Input />
                    </Form.Item>
                ))}
            </>
        )}
    </Form.List>
);
